def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    budget = my_status['budget']
    hp = my_status['hp']
    no_water = my_status['no_water_days']
    supply = day_context['supply']

    alive_opponents = []
    for opp in opponents_status.values():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        if hp <= 2 or no_water >= 1:
            return min(budget, 50)
        return min(budget, 28)

    total_players = 1 + len(alive_opponents)
    expected_coverage = float(supply) / float(WATER_REQ)
    scarcity = total_players - expected_coverage

    prev_bids = []
    desperate_count = 0
    rich_aggressive = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev['bid'])
        if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 3:
            desperate_count += 1
        if opp.get('budget', 0) > budget and prev and prev.get('bid') is not None and prev.get('bid') >= 45:
            rich_aggressive += 1

    if hp <= 2:
        base = 62
    elif no_water >= 2:
        base = 60
    elif no_water >= 1:
        base = 50
    else:
        if scarcity >= 2.5:
            base = 48
        elif scarcity >= 1.5:
            base = 40
        elif scarcity >= 0.5:
            base = 33
        else:
            base = 24

    if prev_bids:
        highest_prev = max(prev_bids)
        if hp <= 3 or no_water >= 1:
            base = max(base, min(65, highest_prev + 3))
        else:
            if highest_prev >= 60:
                base = min(base, 30)
            elif highest_prev >= 45:
                base = max(base, 36)
            else:
                base = max(base, highest_prev + 2)

    base += min(desperate_count, 2) * 3
    base += min(rich_aggressive, 2) * 2

    if budget < DAILY_SALARY * 1.2:
        base = min(base, 42)
    if budget < DAILY_SALARY * 0.7:
        base = min(base, 32)

    if hp >= 7 and no_water == 0 and scarcity < 1 and desperate_count == 0:
        base = min(base, 26)

    bid = max(0, min(budget, base))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = day_context.get('supply', 0)
    day = day_context.get('day', 0)

    hp = my_status.get('hp', 0)
    budget = my_status.get('budget', 0)
    no_water_days = my_status.get('no_water_days', 0)

    alive_opps = [o for o in opponents_status.values() if o.get('alive', False)]

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from each opponent's previous_trace
    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                yesterday_bids.append(float(bid))
            except Exception:
                pass

    # Base target bid
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        # If someone was already bidding very high, they likely need water urgently.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            # If our hp is low or we've already missed water, lean more aggressive.
            urgency = 0.0
            if hp <= 2:
                urgency += 0.35
            if no_water_days >= 2:
                urgency += 0.25
            if no_water_days >= 3:
                urgency += 0.25
            bid_frac = 0.30 + urgency
            bid = DAILY_SALARY * bid_frac
            return max(0.0, min(budget, bid))
        else:
            # Otherwise, bid enough to compete while preserving budget.
            # Slightly overbid relative to their max to steal allocations.
            bid = max(DAILY_SALARY * 0.50, highest_prev_bid + 1.5)
            # If our hp is critical, increase.
            if hp <= 2:
                bid *= 1.35
            if no_water_days >= 2:
                bid *= 1.15
            return max(0.0, min(budget, bid))

    # No reliable yesterday bid info: decide using our internal state.
    if hp <= 2:
        return max(0.0, min(budget, DAILY_SALARY * 0.90))
    if no_water_days >= 3:
        return max(0.0, min(budget, DAILY_SALARY * 0.75))
    if no_water_days >= 2:
        return max(0.0, min(budget, DAILY_SALARY * 0.65))

    # Mild bid; scale with supply (higher supply => can bid less aggressively).
    # Ensure indices are safe: we only use scalar math.
    # Map supply in [15,25] to a factor in [0.55,0.40]
    s = float(supply)
    if s <= 15.0:
        factor = 0.55
    elif s >= 25.0:
        factor = 0.40
    else:
        factor = 0.55 - (s - 15.0) * (0.15 / 10.0)

    bid = DAILY_SALARY * factor
    return max(0.0, min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.15)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    current_bid = 0.0

    if my_status['hp'] <= 1:
        current_bid = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 2:
        current_bid = DAILY_SALARY * 0.85
    elif my_status['hp'] <= 3:
        current_bid = DAILY_SALARY * 0.7
    else:
        current_bid = DAILY_SALARY * 0.5

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if highest_prev_bid >= DAILY_SALARY * 0.75:
            if my_status['hp'] <= 2:
                current_bid = max(current_bid, highest_prev_bid + 5.0)
            else:
                current_bid = max(current_bid, highest_prev_bid * 1.05)
        else:
            current_bid = max(current_bid, highest_prev_bid + 1.0)

    current_supply = day_context['supply']
    if current_supply <= MIN_SUPPLY + (MAX_SUPPLY - MIN_SUPPLY) * 0.25:
        current_bid *= 1.1
    elif current_supply >= MAX_SUPPLY - (MAX_SUPPLY - MIN_SUPPLY) * 0.25:
        current_bid *= 0.9

    final_bid = min(my_status['budget'], max(0.0, current_bid))

    if final_bid < DAILY_SALARY * 0.05 and my_status['budget'] > 0:
        final_bid = min(my_status['budget'], DAILY_SALARY * 0.05)

    return final_bid

