        # Healthy, conserve budget
        # If opponents bid high yesterday, avoid bidding war
        if max_prev_bid >= DAILY_SALARY * 0.8:
            target = min(budget, DAILY_SALARY * 0.3)
        else:
            target = min(budget, max(DAILY_SALARY * 0.4, max_prev_bid + 0.5))
